-- Simplificar template de e-mail da proposta de atendimento
UPDATE email_templates 
SET body_html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>body{font-family:Arial,sans-serif;line-height:1.6;color:#333}.container{max-width:680px;margin:0 auto;padding:20px}.header{background:#00a884;color:white;padding:28px 32px;text-align:center;border-radius:12px 12px 0 0}.header img{max-height:48px;margin-bottom:12px}.header h1{margin:0;font-size:20px;font-weight:700;letter-spacing:-0.3px}.content{background:#ffffff;padding:32px;border:1px solid #e5e7eb;border-top:none}.section{background:#f9fafb;padding:18px 20px;margin:20px 0;border-radius:8px}.section-title{margin:0 0 10px;font-size:15px;font-weight:700;color:#374151}.info-row{margin:4px 0;font-size:14px}.label{font-weight:bold;color:#374151}.value{color:#4b5563}.value-highlight{color:#059669;font-weight:700}.footer{padding:20px 32px;text-align:center;border-radius:0 0 12px 12px;background:#f9fafb;border:1px solid #e5e7eb;border-top:none}.footer p{margin:0;font-size:12px;color:#6b7280}.footer p+p{margin-top:6px}</style></head><body><div class="container"><div class="header"><img src="https://multilife.onsolutionsbrasil.com.br/uploads/logo_1773584168.png" alt="MultiLife Care" /><h1>Proposta de Atendimento Domiciliar</h1></div><div class="content"><p style="font-size:15px;color:#374151">Prezado(a),</p><p style="font-size:14px;color:#4b5563">Encaminhamos proposta de atendimento domiciliar para an&aacute;lise e autoriza&ccedil;&atilde;o, conforme detalhes abaixo.</p><div class="section"><div class="section-title">Servi&ccedil;o Solicitado</div><div class="info-row"><span class="label">Especialidade:</span> <span class="value">{specialty}</span></div><div class="info-row"><span class="label">Servi&ccedil;o:</span> <span class="value">{service_name}</span></div></div><div class="section"><div class="section-title">Valor da Sess&atilde;o</div><div class="info-row"><span class="label">Valor por Sess&atilde;o:</span> <span class="value-highlight">R$ {value_per_session}</span></div></div>{notes_section}<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0" /><p style="font-size:14px;color:#374151">Solicitamos gentilmente a <strong>an&aacute;lise e retorno</strong> sobre esta proposta.</p><p style="font-size:14px;color:#374151"><strong>Para autorizar ou solicitar ajustes, basta responder este e-mail.</strong></p><p style="font-size:14px;color:#6b7280;margin-top:24px">Atenciosamente,<br><strong style="color:#00a884">Equipe MultiLife Care</strong></p></div><div class="footer"><p>Este e-mail foi enviado automaticamente pelo sistema MultiLife Care.</p><p>&copy; 2026 MultiLife Care &mdash; Atendimento Domiciliar</p><p style="margin-top:8px;font-size:11px;color:#9ca3af">Para autorizar, responda diretamente este e-mail.</p></div></div></body></html>',
body_plain = 'Prezado(a),\n\nEncaminhamos proposta de atendimento domiciliar para analise e autorizacao, conforme detalhes abaixo.\n\nSERVICO SOLICITADO\nEspecialidade: {specialty}\nServico: {service_name}\n\nVALOR DA SESSAO\nValor por Sessao: R$ {value_per_session}\n\nSolicitamos gentilmente a analise e retorno sobre esta proposta.\nPara autorizar ou solicitar ajustes, basta responder este e-mail.\n\nAtenciosamente,\nEquipe MultiLife Care'
WHERE event_type = 'proposal_send' AND health_insurer_id IS NULL;
